	if (!r.ok) assert.equal(r.error.code, "invalid-request");
});

check(
	"S-REQ-08: selectorless dispose is allowed and marked selectorless",
	() => {
		const r = validateTransitionRequest({ origin: "model", intent: "dispose" });
