check(
	"a pending transition still allows exactly worktree_session status",
	() => {
		assert.deepEqual(
			decidePendingToolCall({
				toolName: "worktree_session",
				action: "status",
				pending: true,
			}),
			{ allow: true },
		);
		const another = decidePendingToolCall({
			toolName: "worktree_session",
			action: "enter",
			pending: true,
		});
		assert.equal(another.allow, false);
	},
);

